alter table public.exam_sessions add column if not exists result jsonb, add column if not exists finished_by text check (finished_by in ('user','deadline','cleanup')), add column if not exists last_activity_at timestamptz;
create table if not exists public.exam_session_answers (session_id uuid not null references public.exam_sessions(id) on delete cascade, session_question_id uuid not null references public.exam_session_questions(id) on delete cascade, choice text, flagged boolean not null default false, answered_at timestamptz, time_ms int, primary key (session_id, session_question_id));
create table if not exists public.question_reports (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id), session_id uuid not null references public.exam_sessions(id) on delete cascade, user_ref text not null, reason text not null check (reason in ('wrong_answer','typo','missing_image','passage_issue','other')), note text check (note is null or length(note)<=500), status text not null default 'open' check (status in ('open','resolved','dismissed')), created_at timestamptz not null default now(), resolved_at timestamptz, unique(user_ref,question_id,reason));
create table if not exists public.rate_limits (key text not null, window_start timestamptz not null, count int not null default 0, primary key(key,window_start));
create or replace function public.check_rate_limit(p_key text,p_limit int,p_window_seconds int) returns boolean language plpgsql set search_path='' as $$ declare v_start timestamptz:=to_timestamp(floor(extract(epoch from now())/p_window_seconds)*p_window_seconds); v_count int; begin insert into public.rate_limits(key,window_start,count) values(p_key,v_start,1) on conflict(key,window_start) do update set count=public.rate_limits.count+1 returning count into v_count; return v_count<=p_limit; end $$;
create table if not exists public.bank_settings (key text primary key, value jsonb not null);
insert into public.bank_settings(key,value) values ('deadline_grace_seconds','5'),('max_sessions_per_day_free','20'),('max_sessions_per_day_premium','80'),('max_reports_per_hour','10'),('practice_idle_days','7') on conflict(key) do update set value=excluded.value;
alter table public.exam_session_answers enable row level security; alter table public.question_reports enable row level security; alter table public.rate_limits enable row level security; alter table public.bank_settings enable row level security;
revoke all on public.exam_session_answers,public.question_reports,public.rate_limits,public.bank_settings from anon,authenticated; revoke all on function public.check_rate_limit(text,int,int) from public,anon,authenticated;
